import { Icon } from '@/components/ui/icon';
import { IconShell } from '@/components/ui/icon-shell';
import { cn } from '@/lib/utils';

type MatrixType = {
  label: string;
  type: 'neutral' | 'neutral-inverse' | 'custom';
  className?: string;
  dark?: boolean;
};

const MATRIX_TYPES: MatrixType[] = [
  {
    label: 'neutral',
    type: 'neutral',
  },
  {
    label: 'custom',
    type: 'custom',
    className: 'text-status-success',
  },
  {
    label: 'neutral-inverse',
    type: 'neutral-inverse',
    dark: true,
  },
  {
    label: 'custom (inverse)',
    type: 'custom',
    className: 'text-status-success-inverse',
    dark: true,
  },
];

export function IconShellAll() {
  const sizes = ['sm', 'default', 'lg'] as const;
  const states = [
    {
      key: 'secondary',
      variant: 'secondary' as const,
    },
    {
      key: 'primary',
      variant: 'primary' as const,
    },
    {
      key: 'disabled',
      disabled: true,
    },
  ];
  return (
    <div className="space-y-8">
      {MATRIX_TYPES.map(({ label, type, className, dark }) => (
        <div
          key={label}
          className={cn('space-y-4 rounded-lg p-4', dark && 'bg-fill-active')}>
          <span
            className={cn(
              'text-xs font-medium',
              dark ? 'text-fg-primary-inverse' : 'text-fg-secondary',
            )}>
            {label}
          </span>
          {sizes.map(size => (
            <div key={size} className="space-y-2">
              <span
                className={cn(
                  'text-xs capitalize',
                  dark ? 'text-fg-secondary-inverse' : 'text-fg-secondary',
                )}>
                {size}
              </span>
              <div className="flex items-center gap-4">
                {states.map(state => (
                  <IconShell
                    key={state.key}
                    size={size}
                    type={type}
                    variant={state.variant}
                    disabled={state.disabled}
                    className={className}>
                    <Icon icon="crop_free" />
                  </IconShell>
                ))}
              </div>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

